194: /*
195: 	A dynamic array of Plain Old Data. Doesn't support constructors, etc.
196: 	Has a small initial memory pool, so that low or no usage will not
197: 	cause a call to new/delete
198: */
199: template <class T, size_t INITIAL_SIZE>
200: class DynArray
201: {
202: public:
203:     DynArray() :
204:         _mem( _pool ),
205:         _allocated( INITIAL_SIZE ),
206:         _size( 0 )
207:     {
208:     }
209: 
210:     ~DynArray() {
211:         if ( _mem != _pool ) {
212:             delete [] _mem;
213:         }
214:     }
215: 
216:     void Clear() {
217:         _size = 0;
218:     }
219: 
220:     void Push( T t ) {
221:         TIXMLASSERT( _size < INT_MAX );
222:         EnsureCapacity( _size+1 );
223:         _mem[_size] = t;
224:         ++_size;
225:     }
226: 
227:     T* PushArr( size_t count ) {
228:         TIXMLASSERT( _size <= SIZE_MAX - count );
229:         EnsureCapacity( _size+count );
230:         T* ret = &_mem[_size];
231:         _size += count;
232:         return ret;
233:     }
234: 
235:     T Pop() {
236:         TIXMLASSERT( _size > 0 );
237:         --_size;
238:         return _mem[_size];
239:     }
240: 
241:     void PopArr( size_t count ) {
242:         TIXMLASSERT( _size >= count );
243:         _size -= count;
244:     }
245: 
246:     bool Empty() const					{
247:         return _size == 0;
248:     }
249: 
250:     T& operator[](size_t i) {
251:         TIXMLASSERT( i < _size );
252:         return _mem[i];
253:     }
254: 
255:     const T& operator[](size_t i) const {
256:         TIXMLASSERT( i < _size );
257:         return _mem[i];
258:     }
259: 
260:     const T& PeekTop() const            {
261:         TIXMLASSERT( _size > 0 );
262:         return _mem[ _size - 1];
263:     }
264: 
265:     size_t Size() const {
266:         return _size;
267:     }
268: 
269:     size_t Capacity() const {
270:         TIXMLASSERT( _allocated >= INITIAL_SIZE );
271:         return _allocated;
272:     }
273: 
274: 	void SwapRemove(size_t i) {
275: 		TIXMLASSERT(i < _size);
276: 		TIXMLASSERT(_size > 0);
277: 		_mem[i] = _mem[_size - 1];
278: 		--_size;
279: 	}
280: 
281:     const T* Mem() const				{
282:         TIXMLASSERT( _mem );
283:         return _mem;
284:     }
285: 
286:     T* Mem() {
287:         TIXMLASSERT( _mem );
288:         return _mem;
289:     }
290: 
291: private:
292:     DynArray( const DynArray& ); // not supported
293:     void operator=( const DynArray& ); // not supported
294: 
295:     void EnsureCapacity( size_t cap ) {
296:         TIXMLASSERT( cap > 0 );
297:         if ( cap > _allocated ) {
298:             TIXMLASSERT( cap <= SIZE_MAX / 2 / sizeof(T));
299:             const size_t newAllocated = cap * 2;
300:             T* newMem = new T[newAllocated];
301:             TIXMLASSERT( newAllocated >= _size );
302:             memcpy( newMem, _mem, sizeof(T) * _size );	// warning: not using constructors, only works for PODs
303:             if ( _mem != _pool ) {
304:                 delete [] _mem;
305:             }
306:             _mem = newMem;
307:             _allocated = newAllocated;
308:         }
309:     }
310: 
311:     T*  _mem;
312:     T   _pool[INITIAL_SIZE];
313:     size_t _allocated;		// objects allocated
314:     size_t _size;			// number objects in use
315: };
