335: /*
336: 	Template child class to create pools of the correct type.
337: */
338: template< size_t ITEM_SIZE >
339: class MemPoolT : public MemPool
340: {
341: public:
342:     MemPoolT() : _blockPtrs(), _root(0), _currentAllocs(0), _nAllocs(0), _maxAllocs(0), _nUntracked(0)	{}
343:     ~MemPoolT() {
344:         MemPoolT< ITEM_SIZE >::Clear();
345:     }
346: 
347:     void Clear() {
348:         // Delete the blocks.
349:         while( !_blockPtrs.Empty()) {
350:             Block* lastBlock = _blockPtrs.Pop();
351:             delete lastBlock;
352:         }
353:         _root = 0;
354:         _currentAllocs = 0;
355:         _nAllocs = 0;
356:         _maxAllocs = 0;
357:         _nUntracked = 0;
358:     }
359: 
360:     virtual size_t ItemSize() const override {
361:         return ITEM_SIZE;
362:     }
363:     size_t CurrentAllocs() const {
364:         return _currentAllocs;
365:     }
366: 
367:     virtual void* Alloc() override{
368:         if ( !_root ) {
369:             // Need a new block.
370:             Block* block = new Block;
371:             _blockPtrs.Push( block );
372: 
373:             Item* blockItems = block->items;
374:             for( size_t i = 0; i < ITEMS_PER_BLOCK - 1; ++i ) {
375:                 blockItems[i].next = &(blockItems[i + 1]);
376:             }
377:             blockItems[ITEMS_PER_BLOCK - 1].next = 0;
378:             _root = blockItems;
379:         }
380:         Item* const result = _root;
381:         TIXMLASSERT( result != 0 );
382:         _root = _root->next;
383: 
384:         ++_currentAllocs;
385:         if ( _currentAllocs > _maxAllocs ) {
386:             _maxAllocs = _currentAllocs;
387:         }
388:         ++_nAllocs;
389:         ++_nUntracked;
390:         return result;
391:     }
392: 
393:     virtual void Free( void* mem ) override {
394:         if ( !mem ) {
395:             return;
396:         }
397:         --_currentAllocs;
398:         Item* item = static_cast<Item*>( mem );
399: #ifdef TINYXML2_DEBUG
400:         memset( item, 0xfe, sizeof( *item ) );
401: #endif
402:         item->next = _root;
403:         _root = item;
404:     }
405:     void Trace( const char* name ) {
406:         printf( "Mempool %s watermark=%d [%dk] current=%d size=%d nAlloc=%d blocks=%d\n",
407:                 name, _maxAllocs, _maxAllocs * ITEM_SIZE / 1024, _currentAllocs,
408:                 ITEM_SIZE, _nAllocs, _blockPtrs.Size() );
409:     }
410: 
411:     void SetTracked() override {
412:         --_nUntracked;
413:     }
414: 
415:     size_t Untracked() const {
416:         return _nUntracked;
417:     }
418: 
419: 	// This number is perf sensitive. 4k seems like a good tradeoff on my machine.
420: 	// The test file is large, 170k.
421: 	// Release:		VS2010 gcc(no opt)
422: 	//		1k:		4000
423: 	//		2k:		4000
424: 	//		4k:		3900	21000
425: 	//		16k:	5200
426: 	//		32k:	4300
427: 	//		64k:	4000	21000
428:     // Declared public because some compilers do not accept to use ITEMS_PER_BLOCK
429:     // in private part if ITEMS_PER_BLOCK is private
430:     enum { ITEMS_PER_BLOCK = (4 * 1024) / ITEM_SIZE };
431: 
432: private:
433:     MemPoolT( const MemPoolT& ); // not supported
434:     void operator=( const MemPoolT& ); // not supported
435: 
436:     union Item {
437:         Item*   next;
438:         char    itemData[static_cast<size_t>(ITEM_SIZE)];
439:     };
440:     struct Block {
441:         Item items[ITEMS_PER_BLOCK];
442:     };
443:     DynArray< Block*, 10 > _blockPtrs;
444:     Item* _root;
445: 
446:     size_t _currentAllocs;
447:     size_t _nAllocs;
448:     size_t _maxAllocs;
449:     size_t _nUntracked;
450: };
